/**
 * First-person wording for the Initial Assessment (client request, Oct 2026): questions and answers
 * are written in the service user's own words ("I…", "My…"); instructions to Care Professionals
 * start "Please…".
 *
 * Display only. Each entry is matched to a question of the default template by section number +
 * stored `questionText`, and `prisma/scripts/ia-first-person-wording.ts` writes:
 *   - `label`   → `metadata.displayLabel` (shown by the admin form and the PDF instead of the text)
 *   - `options` → the label of each listed option value (values are never changed)
 * The stored `questionText` and option values stay as they are, because risk generation, care-plan
 * rules, the PDF, profile sync and validation match on them.
 *
 * Not reworded yet (awaiting PM / clinical lead): the six falls screening questions. Kept neutral
 * on purpose: validated tool scores and bands, admin fields, and referral / review options such as
 * "GP review requested".
 */
export type IaFirstPersonWording = {
  sectionNumber: number;
  questionText: string;
  label: string;
  /** Option value → first-person label. Values not listed keep their current label. */
  options?: Record<string, string>;
};

